import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Space settings","description":"Plan, seats, Space identifier, and other settings for a Space.","frontmatter":{"title":"Space settings","description":"Plan, seats, Space identifier, and other settings for a Space."},"headers":[],"relativePath":"en/spaces/einstellungen.md","filePath":"en/spaces/einstellungen.md","lastUpdated":1787319236000}'),s={name:"en/spaces/einstellungen.md"};function o(r,e,l,h,d,p){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="space-settings" tabindex="-1">Space settings <a class="header-anchor" href="#space-settings" aria-label="Permalink to &quot;Space settings&quot;">​</a></h1><p>Reachable via <strong>Space settings</strong>. The area is organized into three pages: <strong>General</strong>, <strong>Webhooks</strong>, and <strong>Links</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Don&#39;t confuse this with account settings</p><p><strong>Space settings</strong> apply to <em>one Space</em>. <strong>Profile &amp; settings</strong> apply to <em>you personally</em> — that&#39;s where profile, billing, and API credentials live.</p><p>A common mix-up: the plan is booked per Space, but the payment details are tied to the account.</p></div><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><p>Described as <em>General settings for this Space</em>.</p><h3 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>This Space is on the plan</strong></td><td>The current plan</td></tr><tr><td><strong>Adjust plan and subscription</strong></td><td>Leads to the plan change</td></tr></tbody></table><p>The note below it matters: <em>The owner can adjust the plan.</em> Other roles see the value but can&#39;t change it.</p><h3 id="seats" tabindex="-1">Seats <a class="header-anchor" href="#seats" aria-label="Permalink to &quot;Seats&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Available seats for users with editing rights</strong></td><td>Number of licenses</td></tr><tr><td><strong>Adjust seats</strong></td><td>Changes the number</td></tr></tbody></table><blockquote><p><em>The owner can purchase additional seats for users with editing rights. Read access is free.</em></p></blockquote><p>→ <a href="/en/zusammenarbeit/sitzplaetze">Seats</a></p><h3 id="trial-period" tabindex="-1">Trial period <a class="header-anchor" href="#trial-period" aria-label="Permalink to &quot;Trial period&quot;">​</a></h3><p><strong>Trial period days remaining</strong> shows the remaining time.</p><div class="warning custom-block"><p class="custom-block-title">Check what you&#39;re using before it expires</p><p>Once the trial period ends, the limits of the booked plan apply. Paid settings — especially on forms — can be disabled as a result.</p><p>Note beforehand which features you&#39;re using in production.</p></div><h3 id="info" tabindex="-1">Info <a class="header-anchor" href="#info" aria-label="Permalink to &quot;Info&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Space identifier</strong></td><td>Technical identifier of the Space</td></tr><tr><td><strong>Created at</strong></td><td>Creation date</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">What the identifier is good for</p><p>The Space identifier uniquely identifies the Space — useful for support requests and when working with the <a href="/en/integrationen/api-zugangsdaten">programming interface</a>. You won&#39;t need it for everyday work.</p></div><p>The <strong>Deployment edition</strong> (<em>Stable</em> or <em>Enterprise</em>) is also shown. The app doesn&#39;t explain what distinguishes the editions; ask via chat if you need to know.</p><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><p>Order of sections and number of visible Grids.</p><p>→ <a href="/en/spaces/navigation">Set up navigation</a></p><h2 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h2><p>Outgoing notifications to external systems, triggered by events in a Grid.</p><p>The number allowed per Space depends on the plan.</p><p>→ <a href="/en/integrationen/webhooks">Webhooks</a></p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><p>An overview of <strong>all</strong> external links of this Space:</p><blockquote><p><em>Here&#39;s a list of all external links in this Space</em></p></blockquote><p>This includes form links, view links, portals, flow starts, and invitations.</p><div class="tip custom-block"><p class="custom-block-title">The most important page for an overview</p><p>This is the only place where every externally open access point of a Space is visible in one collected list. Review it regularly — especially after finished projects, expired campaigns, and staff changes.</p></div><p>→ <a href="/en/zusammenarbeit/externe-links">External links at a glance</a></p><h2 id="who-can-change-what" tabindex="-1">Who can change what <a class="header-anchor" href="#who-can-change-what" aria-label="Permalink to &quot;Who can change what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Required</th></tr></thead><tbody><tr><td>Navigation, webhooks, links</td><td><strong>Manage</strong> role</td></tr><tr><td>Plan and seats</td><td><strong>Owner</strong></td></tr><tr><td>Viewing the settings</td><td>any role</td></tr></tbody></table><p>If a button is missing, check your role first. → <a href="/en/fehlerbehebung/fehlende-schaltflaechen">I can&#39;t find a button</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/spaces/navigation">Set up navigation</a></li><li><a href="/en/zusammenarbeit/sitzplaetze">Seats</a></li><li><a href="/en/spaces/space-loeschen">Delete a Space</a></li></ul>',37)])])}const u=t(s,[["render",o]]);export{g as __pageData,u as default};
